class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.data = {}  # dicts preserve insertion order

    def get(self, key: int) -> int:
        if key not in self.data:
            return -1
        val = self.data.pop(key)
        self.data[key] = val          # re-insert as most recent
        return val

    def put(self, key: int, value: int) -> None:
        if key in self.data:
            self.data.pop(key)
        elif len(self.data) == self.capacity:
            self.data.pop(next(iter(self.data)))  # evict oldest
        self.data[key] = value

